\label{lem:polygon}
Let \(P\) be a convex \(m\)-gon of area \(a\) containing a disk of
radius \(r>0\). If \(\beta_1,\ldots,\beta_m\) are its exterior angles,
then
\begin{equation}\label{eq:polygon-area}
 a\ge r^2\sum_{j=1}^m\tan\frac{\beta_j}{2}.
\end{equation}

\label{lem:euler-budget}
For a generic diagram of \(n\) nonempty cells,
\begin{equation}\label{eq:euler-budget}
 M=6n-2-T.
\end{equation}
Thus for \(n=26\), \(M=154-T\).

\label{lem:g-concavity}
The function \(g(x)=1/[x\tan(\pi/x)]\) is strictly increasing and
strictly concave for \(x\ge3\). Consequently
\begin{equation}\label{eq:g-affine}
 g_m\le A+Bm\qquad(m\ge3).
\end{equation}
For a fixed number of integer side counts \(m_j\ge3\) and an upper
bound on their sum, \(\sum_jg_{m_j}\) is maximized by exhausting the
side budget and making the \(m_j\)'s differ by at most one.

\label{lem:finite-certificate}
For
\[
 \mathcal F_{29}=
 \{(m,k):3\le m\le29,\ 0\le k\le\min(4,m),\
                 k=4\Rightarrow m=4\},
\]
one has
\begin{equation}\label{eq:old-plane}
 q_k(m)\le A+Bm+Ck.
\end{equation}
Equality occurs only at \((5,0),(6,0),(4,4)\); every other slack exceeds
\(2.8804896149\times10^{-5}\).

Define
\begin{equation}\label{eq:five-plane-constants}
 h_1=\frac1{1+4\tan(3\pi/16)},\qquad h_2=2-\sqrt3,
\end{equation}
\[
 C_5=h_2-h_1,\qquad
 B_5=g_6-2h_1+h_2,\qquad
 A_5=g_6-6B_5.
\]
Then \(B_5>0\), and for \(0\le k\le3\),
\begin{equation}\label{eq:five-plane}
 q_k(m)\le A_5+B_5m+C_5k\qquad(3\le m\le29).
\end{equation}
The only equalities are \((6,0),(5,1),(5,2)\). If \(k\ge1\) and
\((m,k)\notin\{(5,1),(5,2)\}\), the slack is at least
\begin{equation}\label{eq:delta-star}
 \delta_*:=A_5+4B_5+3C_5-\frac14
 >0.00155222863598066.
\end{equation}
Moreover, with
\begin{equation}\label{eq:delta-zero}
 \delta_0:=A_5+5B_5-g_5
 >0.00133076507398426,
\end{equation}
one has
\begin{equation}\label{eq:unmarked-saving}
 A_5+B_5m-g_m\ge\delta_0(6-m)\qquad(3\le m\le29),
\end{equation}
and \(2\delta_0>\delta_*\). Finally,
\begin{equation}\label{eq:slope-intervals}
\begin{aligned}
 0.00797077920&<g_7-g_6<0.00797077921,\\
 0.01339875050&<g_6-g_5<0.01339875051,
\end{aligned}
\end{equation}
and
\begin{equation}\label{eq:final-intervals}
\begin{aligned}
 26A_5+149B_5+9C_5-\delta_*&<7.380565,\\
 26A+148B+10C&<7.368670.
\end{aligned}
\end{equation}
In addition,
\begin{equation}\label{eq:global-comparison-intervals}
 2g_5+23g_6<7.190081,\qquad
 7.38165296<U^2<7.38165297.
\end{equation}

\label{lem:H-bounds}
\[
 H_3<0.230,\quad H_4<0.2524,\quad H_5<0.263,\quad
 H_m<0.273\quad(m\ge6).
\]
Consequently
\begin{equation}\label{eq:H-envelope}
 H_m\le0.2100+0.0106\min(m,6)\qquad(m\ge3).
\end{equation}
